fn_keys_down:		; function down (asm keyword), Keys.cls line 77
            pop hl		; Keys.cls 78
            ld e, (hl)		; Keys.cls 79
            inc hl		; Keys.cls 80
            ld d, (hl)		; Keys.cls 81
            ld a, d		; Keys.cls 82
            or a		; Keys.cls 83
            jr nz, fn_keys_down_kdno		; Keys.cls 84
            ld a, e		; Keys.cls 85
            cp 64		; Keys.cls 86
            jr nc, fn_keys_down_kdno		; Keys.cls 87
            and 7		; Keys.cls 88
            cp 5		; Keys.cls 89
            jr nc, fn_keys_down_kdno		; Keys.cls 90
            inc a		; Keys.cls 91
            ld d, a                 ; D = bit + 1 [92]
            ld a, e		; Keys.cls 93
            rrca		; Keys.cls 94
            rrca		; Keys.cls 95
            rrca		; Keys.cls 96
            and 7		; Keys.cls 97
            inc a                   ; A = half row + 1 [98]
            ld b, a		; Keys.cls 99
            ld a, #7F		; Keys.cls 100
fn_keys_down_kdrow:		; Keys.cls 101
            rlca                    ; #FE for half row 0, #FD 1 ... #7F 7 [102]
            djnz fn_keys_down_kdrow		; Keys.cls 103
            ld b, a		; Keys.cls 104
            ld c, #FE		; Keys.cls 105
            in a, (c)		; Keys.cls 106
            ld b, d		; Keys.cls 107
fn_keys_down_kdbit:		; Keys.cls 108
            rrca		; Keys.cls 109
            djnz fn_keys_down_kdbit		; Keys.cls 110
            ld de, 0		; Keys.cls 111
            jr c, fn_keys_down_kdset               ; 1 = not pressed [112]
            dec de		; Keys.cls 113
            jr fn_keys_down_kdset		; Keys.cls 114
fn_keys_down_kdno:		; Keys.cls 115
            ld de, 0		; Keys.cls 116
fn_keys_down_kdset:		; Keys.cls 117
            pop hl		; Keys.cls 118
            ld (hl), e		; Keys.cls 119
            inc hl		; Keys.cls 120
            ld (hl), d		; Keys.cls 121
			ret			; end of #asm

fn_keys_joystick:		; function joystick (asm keyword), Keys.cls line 129
            pop hl		; Keys.cls 130
            ld a, (hl)		; Keys.cls 131
            and 1		; Keys.cls 132
            ld bc, #001F		; Keys.cls 133
            jr z, fn_keys_joystick_kjport		; Keys.cls 134
            ld c, #37		; Keys.cls 135
fn_keys_joystick_kjport:		; Keys.cls 136
            in a, (c)               ; Kempston: bit 0 right, 1 left, 2 down, 3 up, 4 fire 1, 5 fire 2 [137]
            ld c, a		; Keys.cls 138
            ld e, 0		; Keys.cls 139
            rrca		; Keys.cls 140
            jr nc, fn_keys_joystick_kjnr		; Keys.cls 141
            set 3, e                ; right [142]
fn_keys_joystick_kjnr:		; Keys.cls 143
            rrca		; Keys.cls 144
            jr nc, fn_keys_joystick_kjnl		; Keys.cls 145
            set 2, e                ; left [146]
fn_keys_joystick_kjnl:		; Keys.cls 147
            rrca		; Keys.cls 148
            jr nc, fn_keys_joystick_kjnd		; Keys.cls 149
            set 1, e                ; down [150]
fn_keys_joystick_kjnd:		; Keys.cls 151
            rrca		; Keys.cls 152
            jr nc, fn_keys_joystick_kjnu		; Keys.cls 153
            set 0, e                ; up [154]
fn_keys_joystick_kjnu:		; Keys.cls 155
            rrca		; Keys.cls 156
            jr nc, fn_keys_joystick_kjn1		; Keys.cls 157
            set 5, e                ; fire 1 [158]
fn_keys_joystick_kjn1:		; Keys.cls 159
            rrca		; Keys.cls 160
            jr nc, fn_keys_joystick_kjn2		; Keys.cls 161
            set 4, e                ; fire 2 [162]
fn_keys_joystick_kjn2:		; Keys.cls 163
            ld d, 0		; Keys.cls 164
            pop hl		; Keys.cls 165
            ld (hl), e		; Keys.cls 166
            inc hl		; Keys.cls 167
            ld (hl), d		; Keys.cls 168
			ret			; end of #asm


